import {ContractError} from './cloud-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {basisBlockers} from './personnel-contract.mjs';
export function createPersonnelEditors({api,h,mount,input,area}){
 return {async employmentDates(id){if((await api.session()).role!=='admin')throw new ContractError('由管理员核对人员适用日期。');const r=(await api.members()).find(r=>r.id===id);if(!r)throw new ContractError('成员档案不可见。');const key=crypto.randomUUID();mount('核对在职适用日期',`<p>${h(r.displayName)}</p>`+input('startDate','入职日期',r.startDate||'','type="date" min="1900-01-01" max="2199-12-31"')+input('endDate','最后在职日（含当天，未离职留空）',r.endDate||'','type="date" min="1900-01-01" max="2199-12-31"')+area('note','本次核对或更正原因（必填）')+'<p class="muted">日期只确定在职适用范围，不自动停用账号、修改角色或折算工资。修改后相关考勤及工资来源会重新核对，历史原值保留。</p>',f=>api.employmentSave(id,{requestKey:key,expectedVersion:r.version,startDate:f.get('startDate')||null,endDate:f.get('endDate')||null,note:f.get('note')}),{kind:'directory'},()=>api.employmentReceipt(key,id));},
 async adminPayrollReview(month,memberId){if(!hasSensitive(await api.session(),'payroll'))throw new ContractError('需要独立薪资授权。');const s=await api.payrollState(month,memberId);if(s.basisKind!=='admin-exempt'||s.basisBlockers.length)throw new ContractError(s.basisBlockers.map(k=>basisBlockers[k]).join('；')||'本月需要核对原考勤记录，不能改用免打卡依据。');const key=crypto.randomUUID();mount('管理员当月免打卡工资依据',`<p>${h(s.member.name)} · ${h(month)}</p><p>在职期间：${h(s.member.startDate)} 至 ${h(s.member.endDate||'未登记结束日')}</p><p>当前为管理员，且本月没有员工考勤历史材料。请明确核对该月工资适用范围，月中入离职等金额仍需人工确认。</p>`+area('note','当月适用情况与核对说明（必填）')+'<label><input name="confirmed" type="checkbox" required>我已核实当月免打卡适用情况及人员日期</label><p class="muted">不生成打卡或正常出勤数据，不豁免员工考勤，不决定工资金额。人员资料或本月历史材料变化后需要重新核对。</p>',f=>api.adminPayrollReviewSave({requestKey:key,month,memberId,expectedReviewId:s.adminReview?.id||null,sourceHash:s.basisHash,note:f.get('note'),confirmed:f.get('confirmed')==='on'}),{kind:'attendance'},()=>api.adminPayrollReviewReceipt(key));}
 };
}
